def rename(uid):
    user = User.query.get(uid)
    user.name = request.json["name"]
    db.session.commit()
    return jsonify(ok=True)

def patch(uid):
    user = User.query.get(uid)
    for key, value in request.json.items():
        setattr(user, key, value)
    db.session.commit()
    return jsonify(ok=True)
